class acceso_logActions extends sfActions
{
  public function preExecute()
  {    
    $isAuthenticated = $this->getUser()->isAuthenticated();
    $base_path = sfConfig::get('base_simad');
    if(!$isAuthenticated){
      $this->redirect($base_path."/backend.php/security/login");
    }
  }

  public function verificaPrilegio($currentForm)
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    if (!$this->getUser()->checkPerm($currentForm, $usuariologuiado)) {
      $this->redirect(sfConfig::get('base_simad') . '/no_autorizado.html');
    }
  }
  public function verificaPrilegioCerrar($currentForm)
  {
    $usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    if (!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)) {
      $this->redirect(sfConfig::get('base_simad') . '/no_autorizado.html');
    }
  }

  public function executeIndex()
  {
    return $this->forward('acceso_log', 'list');
  }

  public function executeList()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $currentForm = "acceso_log/list";
    $this->verificaPrilegio($currentForm);
    //*****************************************************************************
    $c = new Criteria();
    $this->parametros = "&a=1";
    
    if ($this->getRequestParameter('client_ip')) {
      $c->add(AccesoLogPeer::CLIENT_IP, $this->getRequestParameter('client_ip'));
      $this->parametros .= "&client_ip=" . $this->getRequestParameter('client_ip');
    }

    if ($this->getRequestParameter('request_method')) {
      $c->add(AccesoLogPeer::REQUEST_METHOD, $this->getRequestParameter('request_method'));
      $this->parametros .= "&request_method=" . $this->getRequestParameter('request_method');
    }

    if ($this->getRequestParameter('login_status')) {
      $c->add(AccesoLogPeer::LOGIN_STATUS, '%' . $this->getRequestParameter('login_status') . '%', Criteria::LIKE);
      $this->parametros .= "&login_status=" . $this->getRequestParameter('login_status');
    }

    if ($this->getRequestParameter('fechaCreaInicial')) {
      $c->add(AccesoLogPeer::FECHA_CRACION, $this->getRequestParameter('fechaCreaInicial'), Criteria::GREATER_EQUAL);
      $this->parametros .= "&fechaCreaInicial=" . str_replace("/", "-", $this->getRequestParameter('fechaCreaInicial'));
    }
    if ($this->getRequestParameter('fechaCreaFinal')) {
      $c->addAnd(AccesoLogPeer::FECHA_CRACION, $this->getRequestParameter('fechaCreaFinal') . " 23:59", Criteria::LESS_EQUAL);
      $this->parametros .= "&fechaCreaFinal=" . str_replace("/", "-", $this->getRequestParameter('fechaCreaFinal'));
    }

    if ($this->getRequestParameter('user_name')) {
      $c->add(AccesoLogPeer::USER_NAME, '%' . $this->getRequestParameter('user_name') . '%', Criteria::LIKE);
      $this->parametros .= "&user_name=" . $this->getRequestParameter('user_name');
    }

    $c->addDescendingOrderByColumn(AccesoLogPeer::ACCESOLOG_ID);

    $pager = new sfPropelPager('AccesoLog', 25);
    $pager->setCriteria($c);
    $pager->setPage($this->getRequestParameter('page', 1));
    $pager->init();

    $this->pager = $pager;
    $this->controlPaginacion = 1;
  }

