    $c->addSelectColumn(AccesoLogPeer::USER_NAME);
    $c->addSelectColumn(AccesoLogPeer::SCRIPT_NAME);
    //*****************************************************************************
    $this->resultset = AccesoLogPeer::doSelectStmt($c);
    //*****************************************************************************
    $this->setLayout(false);
  }

  public function executeShow()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $currentForm = "acceso_log/show";
    $this->verificaPrilegioCerrar($currentForm);
    //*****************************************************************************
    $this->acceso_log = AccesoLogPeer::retrieveByPk($this->getRequestParameter('accesolog_id'));
    $this->forward404Unless($this->acceso_log);
  }

  public function executeConsulta()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $currentForm = "acceso_log/consulta";
    $this->verificaPrilegio($currentForm);
    //*****************************************************************************
    $this->acceso_log = new AccesoLog();
